solution:
#include <iostream>
#include <string>

class SinhVien {
public:
    explicit SinhVien(const std::string &ten) : ten_(ten) {
        std::cout << "Tao: " << ten_ << "\n";
    }
    ~SinhVien() {
        std::cout << "Huy: " << ten_ << "\n";
    }
    void hienThi() const {
        std::cout << ten_ << "\n";
    }

private:
    std::string ten_;
};

int main() {
    std::string ten;
    std::cin >> ten;
    SinhVien sv(ten);
    sv.hienThi();
    return 0;
}
